def transform(grid):
    # The all-zero row separates the sparse marker grid from the pattern grid.
    sep = next(i for i, row in enumerate(grid) if all(v == 0 for v in row))
    markers = grid[:sep]
    pattern = grid[sep + 1:]
    return [
        [3 if markers[r][c] == 5 and pattern[r][c] == 4 else 5
         for c in range(len(markers[0]))]
        for r in range(len(markers))
    ]
